static void TestImportModuleSpecifierPreferenceShortest(gostd::testing::T* t) {
	tsc::testutil::withRecoverAndFail(t, "Panic on fourslash test", [&] {
		t->Parallel();
		const std::string content = R"TS(// @Filename: /project/src/utils/helper.ts
export const helperFunc = () => {};
// @Filename: /project/src/index.ts
helper/**/)TS";
		auto __fsp1 = fourslash::NewFourslash(t, nullptr, content); auto f = __fsp1.first; auto done = __fsp1.second; TSC_DEFER(done());
		f->Configure(t, lsutil::UserPreferences{.IncludeCompletionsForModuleExports = Tristate::True, .IncludeCompletionsForImportStatements = Tristate::True, .ImportModuleSpecifierPreference = modulespecifiers::ImportModuleSpecifierPreferenceShortest});
		f->VerifyCompletions(t, "", tsu::ptr(fourslash::CompletionsExpectedList{.ItemDefaults = std::make_shared<fourslash::CompletionsExpectedItemDefaults>(fourslash::CompletionsExpectedItemDefaults{.CommitCharacters = std::make_shared<std::vector<std::string>>(tsu::DefaultCommitCharacters), .EditRange = fourslash::Ignored{}}), .Items = std::make_shared<fourslash::CompletionsExpectedItems>(fourslash::CompletionsExpectedItems{.Includes = {"helperFunc"}})}));
		f->BaselineAutoImportsCompletions(t, {""});
	});
}
REGISTER_FOURSLASH_TEST(TestImportModuleSpecifierPreferenceShortest, TestImportModuleSpecifierPreferenceShortest);

