static const std::string objectPropertyNameContent = R"TS(interface Options {
    "a-b": number;
    "c d"?: string;
    "it's"?: number;
    'say "hi"'?: number;
    plain: boolean;
}
const o: Options = {
    /**/
};)TS";
static void configureQuotePreference(gostd::testing::T* t, std::shared_ptr<fourslash::FourslashTest> f, lsutil::QuotePreference quotePreference) {
	t->Helper();
	auto opts = f->GetOptions();
	opts.QuotePreference = quotePreference;
	f->Configure(t, opts);
}

static std::shared_ptr<lsproto::CompletionItem> requiredKey(std::string name) {
	return std::make_shared<lsproto::CompletionItem>(lsproto::CompletionItem{.Label = name});
}

static std::shared_ptr<lsproto::CompletionItem> optionalKey(std::string name) {
	return std::make_shared<lsproto::CompletionItem>(lsproto::CompletionItem{.Label = name + "?", .SortText = std::string(ls::SortTextOptionalMember), .FilterText = name, .InsertText = name});
}

static void verifyObjectLiteralKeyCompletions(gostd::testing::T* t, std::shared_ptr<fourslash::FourslashTest> f, const std::vector<std::shared_ptr<lsproto::CompletionItem>>& items) {
	t->Helper();
	auto expected = std::vector<fourslash::CompletionsExpectedItem>((int)items.size());
	for (size_t i = 0; i < items.size(); i++) {
		auto item = items[i];
		expected[i] = item;
	}
	f->VerifyCompletions(t, "", tsu::ptr(fourslash::CompletionsExpectedList{.IsIncomplete = false, .ItemDefaults = std::make_shared<fourslash::CompletionsExpectedItemDefaults>(fourslash::CompletionsExpectedItemDefaults{.CommitCharacters = std::make_shared<std::vector<std::string>>(tsu::DefaultCommitCharacters), .EditRange = fourslash::Ignored{}}), .Items = std::make_shared<fourslash::CompletionsExpectedItems>(fourslash::CompletionsExpectedItems{.Exact = expected})}));
}

static void TestCompletionsObjectPropertyName_quotePreferenceSingle(gostd::testing::T* t) {
	tsc::testutil::withRecoverAndFail(t, "Panic on fourslash test", [&] {
		t->Parallel();
		const std::string content = R"TS(type TableName = 't1' | 't2';
type ColumnName = 'id' | 'value';
type TableColumn = `${TableName}.${ColumnName}`;

type Join = {
  on: Partial<Record<TableColumn, TableColumn>>;
};

const test: Join = {
  on: {
    /**/
  }
};)TS";
		auto __fsp1 = fourslash::NewFourslash(t, nullptr, content); auto f = __fsp1.first; auto done = __fsp1.second; TSC_DEFER(done());
		configureQuotePreference(t, f, lsutil::QuotePreferenceSingle);
		verifyObjectLiteralKeyCompletions(t, f, {optionalKey("'t1.id'"), optionalKey("'t1.value'"), optionalKey("'t2.id'"), optionalKey("'t2.value'")});
	});
}
REGISTER_FOURSLASH_TEST(TestCompletionsObjectPropertyName_quotePreferenceSingle, TestCompletionsObjectPropertyName_quotePreferenceSingle);

static void TestCompletionsObjectPropertyName_quotePreferenceSingleEscaping(gostd::testing::T* t) {
	tsc::testutil::withRecoverAndFail(t, "Panic on fourslash test", [&] {
		t->Parallel();
		auto __fsp1 = fourslash::NewFourslash(t, nullptr, objectPropertyNameContent); auto f = __fsp1.first; auto done = __fsp1.second; TSC_DEFER(done());
		configureQuotePreference(t, f, lsutil::QuotePreferenceSingle);
		auto spaced = optionalKey("'c d'");
		spaced->Detail = R"TS((property) Options["c d"]?: string | undefined)TS";
		verifyObjectLiteralKeyCompletions(t, f, {requiredKey("'a-b'"), requiredKey("plain"), spaced, optionalKey(R"TS('it\'s')TS"), optionalKey(R"TS('say "hi"')TS")});
	});
}
REGISTER_FOURSLASH_TEST(TestCompletionsObjectPropertyName_quotePreferenceSingleEscaping, TestCompletionsObjectPropertyName_quotePreferenceSingleEscaping);

