static void TestCompletionResolveAfterEdit(gostd::testing::T* t) {
	tsc::testutil::withRecoverAndFail(t, "Panic on fourslash test", [&] {
		t->Parallel();
		const std::string content = R"TS(
// @filename: a.ts
interface I {
	x: number;
	y: number;
}
declare const u: I;
/*a*/

// @filename: 1.ts
/*b*/
)TS";
		auto __fsp1 = fourslash::NewFourslash(t, nullptr, content); auto f = __fsp1.first; auto done = __fsp1.second; TSC_DEFER(done());
		f->GoToMarker(t, "a");
		auto completions = f->GetCompletions(t, nullptr);
		if (completions == nullptr || (int)completions->Items->size() == 0) {
			t->Fatal({"Expected completions but got none"});
		}
		auto firstItem = (*completions->Items)[0];
		f->GoToMarker(t, "b");
		f->Insert(t, "1");
		auto resolved = f->ResolveCompletionItem(t, firstItem);
		if (resolved == nullptr) {
			t->Fatal({"Expected resolved completion item but got nil"});
		}
	});
}
REGISTER_FOURSLASH_TEST(TestCompletionResolveAfterEdit, TestCompletionResolveAfterEdit);

