static void TestCompletionAfterExtendsL10nInJs(gostd::testing::T* t) {
	tsc::testutil::withRecoverAndFail(t, "Panic on fourslash test", [&] {
		t->Parallel();
		const std::string content = R"TS(
// @allowJs: true
// @checkJs: true
// @Filename: /interfaces.d.ts
export interface IL10n {}

// @Filename: /genericl10n.js
/** @typedef {import("./interfaces").IL10n} IL10n */

class L10n {
	constructor(options) {
		this.options = options;
	}
}

/**
 * @implements {IL10n}
 */
class GenericL10n extends L10n/*1*/ {
	constructor(lang) {
		super({ lang });
	}
}

)TS";
		auto __fsp1 = fourslash::NewFourslash(t, nullptr, content); auto f = __fsp1.first; auto done = __fsp1.second; TSC_DEFER(done());
		f->GoToMarker(t, "1");
		f->GetCompletions(t, nullptr);
	});
}
REGISTER_FOURSLASH_TEST(TestCompletionAfterExtendsL10nInJs, TestCompletionAfterExtendsL10nInJs);

